class Lager:
    def __init__(self):
        self._varer = []

    def legg_til(self, v):
        self._varer.append(v)

    def totalt_antall(self):
        sum_a = 0
        for v in self._varer:
            sum_a = sum_a + v.hent_antall()
        return sum_a

lager = Lager()
lager.legg_til(Vare("skrue", 120))
lager.legg_til(Vare("bolt", 45))
print(lager.totalt_antall())
